import { IsString, IsOptional, IsEnum, MaxLength, MinLength } from 'class-validator';

export class BuatCatatanDto {
  @IsString()
  @MinLength(3)
  @MaxLength(200)
  judul: string;

  @IsOptional()
  @IsEnum(['rendah', 'sedang', 'tinggi'])
  prioritas?: 'rendah' | 'sedang' | 'tinggi';
}
